                    <>
                      <div className="grid grid-cols-8 gap-1">
                        {EFFECTS.map((e) => {
                          const I = EFFECT_ICON[e.id];
                          const on = effect === e.id;
                          return (
                            <Tip key={e.id} label={e.label} className="w-full justify-center">
                              {/* Buttons FILL their grid column (w-full) instead of a fixed w-9, so the
                                  7-col grid never has an intrinsic width wider than the icon row — the
                                  w-fit island then only ever morphs open vertically, never left/right. */}
                              <button type="button" onClick={() => { playSound(on ? "off" : "on"); setEffect(on ? null : e.id); }} aria-label={on ? `Turn off ${e.label}` : `Turn on ${e.label}`} aria-pressed={on} className={cn(TOOL, "h-9 w-full [@media(hover:hover)]:hover:[&_svg]:scale-[1.15] [&_svg]:transition-transform [&_svg]:duration-300 [&_svg]:ease-out", on && BTN_ON)}>
                                <I size={18} weight="bold" />
                              </button>
                            </Tip>
                          );
                        })}
                      </div>
                      {/* Opacity sits ABOVE the SV+hue pair, so those two stay anchored at the
                          bottom of the panel — identical to the colour + font tabs. Switching
                          between the three then reads as one shared picker with different extras
                          stacked above it (the effect grid + opacity here, the font list there). */}
                      <Tip label="Opacity" className="mt-2.5">
                        <div onPointerDown={dragFxOpacity} onPointerMove={(e) => e.buttons === 1 && dragFxOpacity(e)} aria-label="Effect opacity" className="relative h-3 w-full cursor-pointer touch-none rounded-md" style={{ background: `linear-gradient(to right, var(--muted), ${fxTinted ? fxSwatch : "var(--foreground)"})` }}>
                          <span className="pointer-events-none absolute top-1/2 h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-[5px] border-2 border-white shadow-[0_0_0_1px_rgba(0,0,0,0.5)]" style={{ left: `${fxOpacity * 100}%`, background: fxTinted ? fxSwatch : "var(--foreground)" }} />
                        </div>
                      </Tip>
                      <Tip label="Effect colour" className="mt-2.5">
                        <div onPointerDown={dragFxSV} onPointerMove={(e) => e.buttons === 1 && dragFxSV(e)} className="relative h-20 w-full cursor-crosshair touch-none rounded-lg" style={{ background: SV_GRAD(`hsl(${fxHue} 100% 50%)`) }}>
                          <span className="pointer-events-none absolute h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-[5px] border-2 border-white shadow-[0_0_0_1px_rgba(0,0,0,0.5)]" style={{ left: `${fxSat * 100}%`, top: `${(1 - fxVal) * 100}%`, background: fxSwatch, opacity: fxTinted ? 1 : 0.85 }} />
                        </div>
                      </Tip>
                      <div onPointerDown={dragFxHue} onPointerMove={(e) => e.buttons === 1 && dragFxHue(e)} className="relative mt-2.5 h-3 w-full cursor-pointer touch-none rounded-md" style={{ background: HUE_BAR }}>
                        <span className="pointer-events-none absolute top-1/2 h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-[5px] border-2 border-white shadow-[0_0_0_1px_rgba(0,0,0,0.5)]" style={{ left: `${(fxHue / 360) * 100}%`, background: `hsl(${fxHue} 100% 50%)` }} />
                      </div>
                    </>
                  ) : (
                    // font picker — the face list on top, then a text/ink colour picker BELOW it
                    // (the SV+hue pair sits at the bottom of the panel, identical in size + place
                    // to the colour + effects tabs, so switching tabs reads as one shared picker
                    // with the font list stacked above). Each row is its own face; tap to apply.
                    // The list scrolls (overscroll-contain keeps a boundary scroll from leaking to
                    // the page). Each preview wears the same x-height normalisation it'll get when
                    // applied, so the row shows its true rendered size.
                    <>
                      <div data-font-scroll className="flex max-h-[228px] flex-col gap-0.5 overflow-y-auto overscroll-contain pr-0.5 [scrollbar-width:thin]">
                      {FONT_NAMES.map((name, i) => (
                        <button
                          key={name}
                          type="button"
                          onClick={() => applyFont(i)}
                          aria-label={`Set font to ${name}`}
                          aria-pressed={fontI === i}
                          className={cn(
                            "flex h-9 shrink-0 items-center rounded-lg px-3 text-[15px] text-muted-foreground outline-none transition-[color,background-color,transform] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] active:scale-[0.98] [@media(hover:hover)]:hover:bg-muted/70 [@media(hover:hover)]:hover:text-foreground",
                            fontI === i && BTN_ON,
                          )}
                          // Inter's preview (FONTS[0] === null) must use the locked copy: the
                          // switcher overwrites --font-inter on the root, so referencing it here
                          // would render this row in the active face instead of real Inter.
                          style={{ fontFamily: FONTS[i] ?? "var(--font-inter-locked)", fontSizeAdjust: FONT_ADJUST[i] ?? "none", letterSpacing: FONT_TRACKING[i] ?? "normal" }}
                        >
                          {name}
                        </button>
                      ))}
                      </div>
                      <Tip label="Text colour" className="mt-3">
                        <div onPointerDown={dragTextSV} onPointerMove={(e) => e.buttons === 1 && dragTextSV(e)} className="relative h-20 w-full cursor-crosshair touch-none rounded-lg" style={{ background: SV_GRAD(`hsl(${fontHue} 100% 50%)`) }}>
                          <span className="pointer-events-none absolute h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-[5px] border-2 border-white shadow-[0_0_0_1px_rgba(0,0,0,0.5)]" style={{ left: `${fontSat * 100}%`, top: `${(1 - fontVal) * 100}%`, background: textSwatch, opacity: textColorActive ? 1 : 0.85 }} />
                        </div>
                      </Tip>
                      <div onPointerDown={dragTextHue} onPointerMove={(e) => e.buttons === 1 && dragTextHue(e)} className="relative mt-2.5 h-3 w-full cursor-pointer touch-none rounded-md" style={{ background: HUE_BAR }}>
                        <span className="pointer-events-none absolute top-1/2 h-3.5 w-3.5 -translate-x-1/2 -translate-y-1/2 rounded-[5px] border-2 border-white shadow-[0_0_0_1px_rgba(0,0,0,0.5)]" style={{ left: `${(fontHue / 360) * 100}%`, background: `hsl(${fontHue} 100% 50%)` }} />
                      </div>
                    </>
                  )}
                </div>
            </motion.div>
          </ToolbarPanel>
        </motion.div>
      </div>
    </>
  );
}

"use client";

import { useEffect, useState } from "react";

/**
 * The element that currently owns the page's vertical scroll: the top-most open
 * full-page post overlay (`[data-overlay]`, which is `fixed inset-0 overflow-y-auto`),
 * or null when the document itself is the scroller. Lets viewport toys (the cat,
 * its poop, ink) anchor to whatever is actually scrolling, so they pin to the post
 * content instead of floating over it.
 */
export function useScrollHost() {
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => {
    const read = () => {
      const all = document.querySelectorAll<HTMLElement>("[data-overlay]");
      setHost(all.length ? all[all.length - 1] : null);
    };
    read();
    const mo = new MutationObserver(read);
    mo.observe(document.body, { childList: true, subtree: true });
    return () => mo.disconnect();
  }, []);
  return host;
}

"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import { Moon, Sun } from "@phosphor-icons/react"
import { flushSync } from "react-dom"

import { cn } from "@/lib/utils"

export type TransitionVariant =
  | "circle"
  | "square"
  | "triangle"
  | "diamond"
  | "hexagon"
  | "rectangle"
  | "star"

interface AnimatedThemeTogglerProps extends React.ComponentPropsWithoutRef<"button"> {
  duration?: number
  variant?: TransitionVariant
  /** When true, the transition expands from the viewport center instead of the button center. */
  fromCenter?: boolean
  /**
   * Controlled theme value. When provided, the parent owns persistence
   * (e.g. `next-themes`) and this component will not write to localStorage.
   */
  theme?: "light" | "dark"
  /** Called on toggle. Pair with `theme` for controlled usage. */
  onThemeChange?: (theme: "light" | "dark") => void
  /** Icon shown while in light mode (the affordance to switch to dark). Defaults to a moon. */
  lightIcon?: React.ReactNode
  /** Icon shown while in dark mode (the affordance to switch to light). Defaults to a sun. */
  darkIcon?: React.ReactNode
  /**
   * When false, toggling only flips local/controlled state — it never touches
   * `document.documentElement`'s class or fires the page-wide View Transition
   * wipe. Defaults to true (the real site-wide toggle). Set false for
   * isolated/demo usage, e.g. a gallery preview, so clicking it can't affect
   * the rest of the page.
   */
  mutateDocument?: boolean
}

function polygonCollapsed(cx: number, cy: number, vertexCount: number): string {
  const pairs = Array.from(
    { length: vertexCount },
    () => `${cx}px ${cy}px`
  ).join(", ")
  return `polygon(${pairs})`
}

function getThemeTransitionClipPaths(
  variant: TransitionVariant,
  cx: number,
  cy: number,
  maxRadius: number,
  viewportWidth: number,
  viewportHeight: number
): [string, string] {
  switch (variant) {
    case "circle":
      return [
        `circle(0px at ${cx}px ${cy}px)`,
        `circle(${maxRadius}px at ${cx}px ${cy}px)`,
      ]
    case "square": {
      const halfW = Math.max(cx, viewportWidth - cx)
      const halfH = Math.max(cy, viewportHeight - cy)
      const halfSide = Math.max(halfW, halfH) * 1.05
      const end = [
        `${cx - halfSide}px ${cy - halfSide}px`,
        `${cx + halfSide}px ${cy - halfSide}px`,
        `${cx + halfSide}px ${cy + halfSide}px`,
        `${cx - halfSide}px ${cy + halfSide}px`,
      ].join(", ")
      return [polygonCollapsed(cx, cy, 4), `polygon(${end})`]
    }
    case "triangle": {
      const scale = maxRadius * 2.2
      const dx = (Math.sqrt(3) / 2) * scale
      const verts = [
        `${cx}px ${cy - scale}px`,
        `${cx + dx}px ${cy + 0.5 * scale}px`,
        `${cx - dx}px ${cy + 0.5 * scale}px`,
      ].join(", ")
      return [polygonCollapsed(cx, cy, 3), `polygon(${verts})`]
    }
    case "diamond": {
      // Slightly larger than the view-transition circle radius so axis-aligned coverage matches the circle reveal.
      const R = maxRadius * Math.SQRT2
      const end = [
        `${cx}px ${cy - R}px`,
        `${cx + R}px ${cy}px`,
        `${cx}px ${cy + R}px`,
        `${cx - R}px ${cy}px`,
      ].join(", ")
      return [polygonCollapsed(cx, cy, 4), `polygon(${end})`]
    }
    case "hexagon": {
      const R = maxRadius * Math.SQRT2
      const verts: string[] = []
      for (let i = 0; i < 6; i++) {
        const a = -Math.PI / 2 + (i * Math.PI) / 3
        verts.push(`${cx + R * Math.cos(a)}px ${cy + R * Math.sin(a)}px`)
      }
      return [polygonCollapsed(cx, cy, 6), `polygon(${verts.join(", ")})`]
    }
    case "rectangle": {
      const halfW = Math.max(cx, viewportWidth - cx)
      const halfH = Math.max(cy, viewportHeight - cy)
      const end = [
        `${cx - halfW}px ${cy - halfH}px`,
        `${cx + halfW}px ${cy - halfH}px`,
        `${cx + halfW}px ${cy + halfH}px`,
        `${cx - halfW}px ${cy + halfH}px`,
      ].join(", ")
      return [polygonCollapsed(cx, cy, 4), `polygon(${end})`]
    }
    case "star": {
      // Small overscan so the last frames never leave a 1px seam before the transition group ends.
      const R = maxRadius * Math.SQRT2 * 1.03
      const innerRatio = 0.42
      const starPolygon = (radius: number) => {
        const verts: string[] = []
        for (let i = 0; i < 5; i++) {
          const outerA = -Math.PI / 2 + (i * 2 * Math.PI) / 5
          verts.push(
            `${cx + radius * Math.cos(outerA)}px ${cy + radius * Math.sin(outerA)}px`
          )
          const innerA = outerA + Math.PI / 5
          verts.push(
            `${cx + radius * innerRatio * Math.cos(innerA)}px ${cy + radius * innerRatio * Math.sin(innerA)}px`
          )
        }
        return `polygon(${verts.join(", ")})`
      }
      const startR = Math.max(2, R * 0.025)
      return [starPolygon(startR), starPolygon(R)]
    }
    default:
      return [
        `circle(0px at ${cx}px ${cy}px)`,
        `circle(${maxRadius}px at ${cx}px ${cy}px)`,
      ]
  }
}

export const AnimatedThemeToggler = ({
  className,
  duration = 400,
  variant,
  fromCenter = false,
  theme,
  onThemeChange,
  lightIcon,
  darkIcon,
  mutateDocument = true,
  ...props
}: AnimatedThemeTogglerProps) => {
  const shape = variant ?? "circle"
  const isControlled = theme !== undefined
  const [internalIsDark, setInternalIsDark] = useState(false)
  const isDark = isControlled ? theme === "dark" : internalIsDark
  const buttonRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    if (isControlled) return

    const updateTheme = () => {
      setInternalIsDark(document.documentElement.classList.contains("dark"))
    }

    updateTheme()

    const observer = new MutationObserver(updateTheme)
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class"],
    })

    return () => observer.disconnect()
  }, [isControlled])

  const toggleTheme = useCallback(() => {
    const button = buttonRef.current
    if (!button) return

    if (!mutateDocument) {
      // Local/demo usage: flip only local or controlled state, never the
      // document root class or the page-wide view transition wipe.
      const newTheme = !isDark
      if (isControlled) {
        onThemeChange?.(newTheme ? "dark" : "light")
      } else {
        setInternalIsDark(newTheme)
      }
      return
    }

    const viewportWidth = window.visualViewport?.width ?? window.innerWidth
    const viewportHeight = window.visualViewport?.height ?? window.innerHeight

    let x: number
    let y: number
    if (fromCenter) {
      x = viewportWidth / 2
      y = viewportHeight / 2
    } else {
      const { top, left, width, height } = button.getBoundingClientRect()
      x = left + width / 2
      y = top + height / 2
    }

    const maxRadius = Math.hypot(
      Math.max(x, viewportWidth - x),
      Math.max(y, viewportHeight - y)
    )

    const applyTheme = () => {
      const newTheme = !isDark
      // Always toggle the class synchronously so the View Transitions API
      // snapshots the new theme inside the startViewTransition callback.
      document.documentElement.classList.toggle("dark")
      if (isControlled) {
        onThemeChange?.(newTheme ? "dark" : "light")
      } else {
        setInternalIsDark(newTheme)
        localStorage.setItem("theme", newTheme ? "dark" : "light")
      }
    }

    if (typeof document.startViewTransition !== "function") {
      applyTheme()
      return
    }

    const clipPath = getThemeTransitionClipPaths(
      shape,
      x,
      y,
      maxRadius,
      viewportWidth,
      viewportHeight
    )

    const root = document.documentElement
    root.dataset.magicuiThemeVt = "active"
    root.style.setProperty(
      "--magicui-theme-toggle-vt-duration",
      `${duration}ms`
    )
    // Pin the collapsed clip-path via CSS so Firefox does not paint the new
    // theme unclipped between snapshot and the ready.then() JS animation.
    root.style.setProperty("--magicui-theme-vt-clip-from", clipPath[0])
    const cleanup = () => {
      delete root.dataset.magicuiThemeVt
      root.style.removeProperty("--magicui-theme-toggle-vt-duration")
      root.style.removeProperty("--magicui-theme-vt-clip-from")
    }

    const transition = document.startViewTransition(() => {
      flushSync(applyTheme)
    })
    if (typeof transition?.finished?.finally === "function") {
      transition.finished.finally(cleanup)
    } else {
      cleanup()
    }

    const ready = transition?.ready
    if (ready && typeof ready.then === "function") {
      ready.then(() => {
        document.documentElement.animate(
          {
            clipPath,
          },
          {
            duration,
            // Star: linear avoids easing overshoot that fights polygon interpolation at t→1; VT group duration is synced above.
            easing: shape === "star" ? "linear" : "cubic-bezier(0.23, 1, 0.32, 1)",
            fill: "forwards",
            pseudoElement: "::view-transition-new(root)",
          }
        )
      })
    }
  }, [shape, fromCenter, duration, isDark, isControlled, onThemeChange, mutateDocument])

  return (
    <button
      type="button"
      ref={buttonRef}
      onClick={toggleTheme}
      className={cn(className)}
      {...props}
    >
      {isDark ? (darkIcon ?? <Sun />) : (lightIcon ?? <Moon />)}
      <span className="sr-only">Toggle theme</span>
    </button>
  )
}

"use client";

import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { useReducedMotion } from "motion/react";
import { useScrollHost } from "@/hooks/useScrollHost";

/**
 * Oneko — the classic pixel cat that chases the cursor. A faithful port of the
 * frame-by-frame sprite behaviour: it runs toward the pointer in eight directions
 * (two frames each), throws up an "alert" frame the instant it notices you before
 * it commits to the chase, sits when it catches up, and after idling long enough
 * washes itself or curls up to sleep. Poke the cat and it drops a poop that stays,
 * then fades. Reads position from a single 256x128 sprite sheet via background
 * offsets. Follows the pointer on desktop and taps on touch; calmed under reduced motion.
 */

// sprite-sheet cells, in 32px units (x, y). Straight from oneko's frame map.
const SPRITES: Record<string, [number, number][]> = {
  idle: [[-3, -3]],
  alert: [[-7, -3]],
  scratchSelf: [[-5, 0], [-6, 0], [-7, 0]],
  scratchWallN: [[0, 0], [0, -1]],
  scratchWallS: [[-7, -1], [-6, -2]],
  scratchWallE: [[-2, -2], [-2, -3]],
  scratchWallW: [[-4, 0], [-4, -1]],
  tired: [[-3, -2]],
  sleeping: [[-2, 0], [-2, -1]],
  N: [[-1, -2], [-1, -3]],
  NE: [[0, -2], [0, -3]],
  E: [[-3, 0], [-3, -1]],
  SE: [[-5, -1], [-5, -2]],
  S: [[-6, -3], [-7, -2]],
  SW: [[-5, -3], [-6, -1]],
  W: [[-4, -2], [-4, -3]],
  NW: [[-1, 0], [-1, -1]],
};

type Poop = { id: number; x: number; y: number };

export function CatCursor({ active }: { active: boolean }) {
  const nekoRef = useRef<HTMLDivElement>(null);
  const posRef = useRef({ x: 0, y: 0 });
  const cursorRef = useRef({ x: 0, y: 0 }); // last cursor, viewport coords (persists across host changes)
  const reactRef = useRef(0); // startled window after a poke
  const poopId = useRef(0);
  const reduce = useReducedMotion();
  const host = useScrollHost(); // the open post overlay that owns scroll, or null
  const [mounted, setMounted] = useState(false);
  const [poops, setPoops] = useState<Poop[]>([]);

  useEffect(() => setMounted(true), []);
  // poops belong to the context they were dropped in — clear them when the scroll
  // host changes (a post opening/closing) so none linger with stale coordinates
  useEffect(() => setPoops([]), [host]);

  // track the cursor globally so the cat keeps its bearings across host swaps
  useEffect(() => {
    cursorRef.current = { x: window.innerWidth / 2, y: window.innerHeight / 2 };
    const onMove = (e: PointerEvent) => { cursorRef.current = { x: e.clientX, y: e.clientY }; };
    window.addEventListener("pointermove", onMove, { passive: true });
    window.addEventListener("pointerdown", onMove, { passive: true });
    return () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerdown", onMove);
    };
  }, []);

  useEffect(() => {
    if (!active) return;
    const neko = nekoRef.current;
    if (!neko) return;

    const TICK_MS = 100;
    const SPEED = 14; // px per tick (10fps) — a calm ~140px/s trot
    // The cat lives in the CONTENT space of whatever is scrolling — the document,
    // or the open post overlay. So it stays put on the content as you scroll and has
    // to run to catch back up to the cursor, instead of floating with the viewport.
    // Pointer/viewport coordinates are physical CSS pixels, while a portal inside
    // the narrow layout uses the body's zoomed content coordinates.
    const scale = () => host
      ? host.getBoundingClientRect().width / host.offsetWidth || 1
      : Number.parseFloat(getComputedStyle(document.body).zoom) || 1;
    const pointer = () => {
      const zoom = scale();
      const rect = host?.getBoundingClientRect();
      return {
        x: (cursorRef.current.x - (rect?.left ?? 0)) / zoom + (host ? host.scrollLeft : window.scrollX / zoom),
        y: (cursorRef.current.y - (rect?.top ?? 0)) / zoom + (host ? host.scrollTop : window.scrollY / zoom),
      };
    };
    const maxW = () => host ? host.scrollWidth : document.documentElement.scrollWidth / scale();
    const maxH = () => host ? host.scrollHeight : document.documentElement.scrollHeight / scale();

    let { x: nekoX, y: nekoY } = pointer();
    let frameCount = 0;
    let idleTime = 0;
    let idleAnim: string | null = null;
    let idleFrame = 0;

    const setSprite = (name: string, frame: number) => {
      const set = SPRITES[name];
      // Enabling the cat explicitly opts into its running animation. Freezing
      // these frames while it still moves makes it slide instead of run.
      const [sx, sy] = set[frame % set.length];
      neko.style.backgroundPosition = `${sx * 32}px ${sy * 32}px`;
    };
    const place = (x = nekoX, y = nekoY) => {
      neko.style.transform = `translate3d(${(x - 16).toFixed(1)}px, ${(y - 16).toFixed(1)}px, 0)`;
      posRef.current = { x, y };
    };
    const resetIdle = () => { idleAnim = null; idleFrame = 0; };

    const idle = () => {
      idleTime += 1;
      // occasionally pick a longer idle routine — wash, or curl up to sleep
      if (!reduce && idleTime > 10 && idleAnim == null && Math.floor(Math.random() * 200) === 0) {
        const avail = ["sleeping", "scratchSelf"];
        if (nekoX < 32) avail.push("scratchWallW");
        if (nekoY < 32) avail.push("scratchWallN");
        if (nekoX > maxW() - 32) avail.push("scratchWallE");
        if (nekoY > maxH() - 32) avail.push("scratchWallS");
        idleAnim = avail[Math.floor(Math.random() * avail.length)];
        idleFrame = 0;
      }
      switch (idleAnim) {
        case "sleeping":
          if (idleFrame < 8) { setSprite("tired", 0); break; } // yawn/settle first
          setSprite("sleeping", Math.floor(idleFrame / 4));
          if (idleFrame > 192) resetIdle();
          break;
        case "scratchWallN":
        case "scratchWallS":
        case "scratchWallE":
        case "scratchWallW":
        case "scratchSelf":
          setSprite(idleAnim, idleFrame);
          if (idleFrame > 9) resetIdle();
          break;
        default:
          setSprite("idle", 0);
          return;
      }
      idleFrame += 1;
    };

    const tick = () => {
      frameCount += 1;
      const now = performance.now();

      // just poked → startled for a beat
      if (now < reactRef.current) { setSprite("alert", 0); return; }

      // cursor target in content coords — recomputed every tick, so simply scrolling
      // (cursor still) moves the target and the cat has to run to catch up
      const { x: mouseX, y: mouseY } = pointer();

      const diffX = nekoX - mouseX;
      const diffY = nekoY - mouseY;
      const dist = Math.hypot(diffX, diffY);

      // close enough → sit / idle behaviours, keeps a gap so it's pokeable
      if (dist < SPEED || dist < 48) { idle(); return; }

      resetIdle();

      // the "decides to follow" beat: after resting, hold an alert frame a few
      // ticks before committing to the chase, then go
      if (idleTime > 1) {
        setSprite("alert", 0);
        idleTime = Math.min(idleTime, 7) - 1;
        return;
      }

      let dir = "";
      dir += diffY / dist > 0.5 ? "N" : "";
      dir += diffY / dist < -0.5 ? "S" : "";
      dir += diffX / dist > 0.5 ? "W" : "";
      dir += diffX / dist < -0.5 ? "E" : "";
      setSprite(dir || "idle", frameCount);

      nekoX -= (diffX / dist) * SPEED;
      nekoY -= (diffY / dist) * SPEED;
      nekoX = Math.max(16, Math.min(maxW() - 16, nekoX));
      nekoY = Math.max(16, Math.min(maxH() - 16, nekoY));
    };

    place();
    setSprite("idle", 0);
    // Keep the original 10fps sprite cadence and interpolate between those steps
    // so the cat follows with the same relaxed trailing motion as before.
    let previousX = nekoX;
    let previousY = nekoY;
    let tickAt = performance.now();
    let raf = 0;
    const frame = (now: number) => {
      if (now - tickAt >= TICK_MS) {
        previousX = nekoX;
        previousY = nekoY;
        tick();
        tickAt = now;
      }
      const progress = Math.min(1, (now - tickAt) / TICK_MS);
      place(previousX + (nekoX - previousX) * progress, previousY + (nekoY - previousY) * progress);
      raf = requestAnimationFrame(frame);
    };
    const onVisibility = () => {
      cancelAnimationFrame(raf);
      if (!document.hidden) {
        previousX = nekoX;
        previousY = nekoY;
        tickAt = performance.now();
        raf = requestAnimationFrame(frame);
      }
    };
    if (!document.hidden) raf = requestAnimationFrame(frame);
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      cancelAnimationFrame(raf);
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [active, reduce, mounted, host]);

  const dropPoop = (e: React.PointerEvent) => {
    e.preventDefault();
    e.stopPropagation();
    reactRef.current = performance.now() + 300; // startled little jump
    // posRef is already in page coords (so is the cat), so the poop stays put on scroll
    const { x, y } = posRef.current;
    const id = ++poopId.current;
    setPoops((p) => [...p, { id, x, y: y + 8 }]);
    window.setTimeout(() => setPoops((p) => p.filter((q) => q.id !== id)), 9000);
  };

  if (!active) return null;

  return (
    <>
      <style>{`
        .oneko-poop { animation: oneko-poop-in 0.24s var(--ease-out) both, oneko-poop-out 0.6s var(--ease-out) 8.4s both; }
        @keyframes oneko-poop-in { from { transform: scale(0) translateY(-4px); opacity: 0; } to { transform: none; opacity: 1; } }
        @keyframes oneko-poop-out { to { opacity: 0; transform: scale(0.85); } }
        @media (prefers-reduced-motion: reduce) { .oneko-poop { animation: none; } }
        /* When a post is hovered the site-wide focus scrim blurs the page, the ink
           and the poop (all below it). The cat sits above the scrim, so blur it in
           place to match — it recedes with everything else instead of staying sharp. */
        .oneko-cat { transition: filter 0.2s var(--ease-out), opacity 0.2s var(--ease-out); }
        html.post-focus .oneko-cat { filter: blur(2.5px); opacity: 0.45; }
      `}</style>

      {mounted && createPortal(
        <>
          {/* absolute + content coords (portalled into the scroll host) so it stays
              where it was dropped and scrolls with the content, like the ink strokes */}
          {poops.map((p) => (
            <div key={p.id} aria-hidden className="oneko-poop pointer-events-none absolute z-[24]" style={{ left: p.x - 7, top: p.y }}>
              <PixelPoop />
            </div>
          ))}

          {/* the cat also lives in page space (absolute), so scrolling leaves it
              behind and it has to run to catch back up to the cursor */}
          <div
            ref={nekoRef}
            role="button"
            tabIndex={-1}
            aria-label="Poke the cat"
            onPointerDown={dropPoop}
            className="oneko-cat absolute left-0 top-0 z-[200] cursor-pointer"
            style={{
              width: 32,
              height: 32,
              backgroundImage: "url(/oneko.png)",
              backgroundRepeat: "no-repeat",
              backgroundPosition: "-96px -96px",
              imageRendering: "pixelated",
            }}
          />
        </>,
        host ?? document.body,
      )}
    </>
  );
}

function PixelPoop() {
  // a tiny pixel-art poop coil to match oneko's aesthetic
  const d = "#6b4a30"; // dark brown
  const l = "#815a3a"; // lighter top
  return (
    <svg width="14" height="12" viewBox="0 0 7 6" style={{ imageRendering: "pixelated", display: "block" }} shapeRendering="crispEdges">
      <rect x="1" y="5" width="5" height="1" fill={d} />
      <rect x="1" y="4" width="5" height="1" fill={d} />
      <rect x="2" y="3" width="4" height="1" fill={d} />
      <rect x="2" y="2" width="3" height="1" fill={l} />
      <rect x="3" y="1" width="2" height="1" fill={l} />
      <rect x="3" y="0" width="1" height="1" fill={l} />
    </svg>
  );
}

/**
 * A side-profile cat body (not a face): head with two ears, a rounded body, four
 * legs, and an upright curling tail. Fills with currentColor. Used static as the
 * toolbar's cat icon and animated (legs + tail) inside the CatCursor.
 */
export function CatMark({ className }: { className?: string }) {
  return (
    <svg viewBox="0 0 30 24" fill="currentColor" className={className}>
      {/* tail — sweeps up from the back */}
      <path
        className="cat-tail"
        d="M6.5 15 Q1.5 13.5 3 6.5"
        fill="none"
        stroke="currentColor"
        strokeWidth="2.4"
        strokeLinecap="round"
      />
      {/* back legs */}
      <rect className="leg-b" x="7.4" y="15.5" width="2.2" height="7" rx="1.1" />
      <rect className="leg-a" x="10.3" y="15.5" width="2.2" height="7" rx="1.1" />
      {/* front legs */}
      <rect className="leg-a" x="18.1" y="15.5" width="2.2" height="7" rx="1.1" />
      <rect className="leg-b" x="21" y="15.5" width="2.2" height="7" rx="1.1" />
      {/* body + head (bobs while running) */}
      <g className="cat-body">
        <path d="M6 14.5 C6 10.5 8.6 8.5 12.5 8.5 L18 8.5 C20.8 8.5 22.4 10 22.4 12.6 L22.4 15.6 C22.4 17.4 21 18.2 18.8 18.2 L9.4 18.2 C7.2 18.2 6 16.8 6 14.5 Z" />
        <circle cx="23" cy="9" r="4.7" />
        {/* ears */}
        <path d="M19.2 6.2 L20.1 1.7 L22.5 5.2 Z" />
        <path d="M23.7 5.2 L26.1 1.7 L27 6.2 Z" />
        {/* eye notch (background-coloured) */}
        <circle cx="24.6" cy="8.6" r="0.95" fill="var(--background)" />
      </g>
    </svg>
  );
}

"use client";

